pub static FALLBACKS: &[(u32, u32)] = &[
    (59392, Idx::_0XE8000XEE00_STANDARDIZED_SINGLE_FRAME_ADDRESSED as u32),
    (61184, Idx::_0XEF00_MANUFACTURER_PROPRIETARY_SINGLE_FRAME_ADDRESSED as u32),
    (61440, Idx::_0XF0000XFEFF_STANDARDIZED_SINGLE_FRAME_NON_ADDRESSED as u32),
    (65280, Idx::_0XFF000XFFFF_MANUFACTURER_PROPRIETARY_SINGLE_FRAME_NON_ADDRESSED as u32),
    (126208, Idx::_0X1ED000X1EE00_STANDARDIZED_FAST_PACKET_ADDRESSED as u32),
    (126720, Idx::_0X1EF00_MANUFACTURER_PROPRIETARY_FAST_PACKET_ADDRESSED as u32),
    (126976, Idx::_0X1F0000X1FEFF_STANDARDIZED_MIXED_SINGLE_FAST_PACKET_NON_ADDRESSED as u32),
    (130816, Idx::_0X1FF000X1FFFF_MANUFACTURER_SPECIFIC_FAST_PACKET_NON_ADDRESSED as u32),
];
/// Largest Fallback:true PgnInfo whose pgn number is <= `pgn`.
/// Mirrors canboat's `searchForUnknownPgn`.
pub fn find_catchall(pgn: u32) -> Option<usize> {
    let i = FALLBACKS.partition_point(|&(p, _)| p <= pgn);
    if i == 0 { None } else { Some(FALLBACKS[i - 1].1 as usize) }
}
